$('export').onclick=()=>busy($('export'),async()=>{const backup={date:new Date().toISOString(),version:1};for(const name of ['profiles','posts','comments','likes','announcements']){backup[name]=[];for(let offset=0;;offset+=500){const rows=await table(name,'select=*&limit=500&offset='+offset+'&order='+({profiles:'id',posts:'id',comments:'id',likes:'post_id,user_id',announcements:'id'}[name]));backup[name].push(...rows);if(rows.length<500)break}}const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));const a=element('a');a.href=url;a.download='family-news-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تنزيل نسخة السجلات. الصور محفوظة بصورة مستقلة.')});
async function deletePost(p){
 if(!confirm('حذف الخبر نهائيًا مع تعليقاته وإعجاباته؟ لا يمكن استعادته بعد الحذف.'))return;
 const removed=await table('posts','id=eq.'+p.id,{method:'DELETE'});
 if(!removed?.length)throw new Error('لم يُحذف الخبر. تحقق من صلاحياتك ثم حدّث الصفحة.');
 let clean=true;
 for(const path of imagePaths(removed[0])){try{const remaining=await table('posts','select=id&image_paths=cs.'+encodeURIComponent('{'+path+'}')+'&limit=1');if(!remaining.length)await req('/storage/v1/object/news-images',{method:'DELETE',body:{prefixes:[path]}})}catch{clean=false}}
 toast(clean?'تم حذف الخبر نهائيًا.':'حُذف الخبر، وتعذّر تنظيف ملف صورته.');
 if(!$('trash-section').hidden)await trash();else await feed(true);
}
let adExpiryTimer;
function paintAnnouncements(){
 const now=Date.now(),box=$('announcement-strip');box.replaceChildren();
 const active=state.ads.filter(ad=>!ad.is_popup && announcementState(ad,now)==='active');
 box.hidden=active.length===0;box.setAttribute('role','group');
 for(const ad of active){const card=button('',()=>showAdDetails(ad),'announcement-banner ad-'+(ad.category||'general'));const title=element('span',ad.title?.trim()||'إعلان العائلة','announcement-title');card.append(icon(({wedding:'heart',death:'archive',commercial:'storage',urgent:'info',donation:'heart'})[ad.category]||'bell'),title);card.title=title.textContent;card.setAttribute('aria-label','تفاصيل الإعلان: '+title.textContent);box.append(card)}
 fitAnnouncements(box);
 clearTimeout(adExpiryTimer);
 const next=state.ads.flatMap(ad=>[Date.parse(ad.starts_at),Date.parse(ad.ends_at)]).filter(t=>t>now).sort((a,b)=>a-b)[0];
 if(next)adExpiryTimer=setTimeout(paintAnnouncements,Math.min(next-now+20,2147483647));
}
